INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('kublai-court-at-kaiping', '忽必烈以开平为汗廷', 'politics', 'point', 'year', '中统元年（1260年）；此时汗位之争未结束，不将开平写成蒙古帝国唯一都城。', 1260, 12, 15131, NULL, NULL, NULL, NULL, NULL, NULL, '忽必烈在开平即大汗位，与仍据和林的阿里不哥争位；开平成为忽必烈一方的政治中心，蒙古帝国一度出现两个汗廷。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('kublai-moves-capital-to-zhongdu', '忽必烈迁都中都', 'politics', 'point', 'year', '至元四年（1267年）；北京地方志资料记为迁都中都之年。', 1267, 12, 15215, NULL, NULL, NULL, NULL, NULL, NULL, '忽必烈由上都迁往中都（今北京），上都转为陪都，并在中都东北营建新城。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('zhou-nanwang-moves-to-western-zhou-capital', '赧王徙居西周', 'politics', 'point', 'year', '仅知周赧王时期发生，具体年份有异说；以都城资料采用的约前314年作为年精度锚点。', -314, 12, -3745, NULL, NULL, NULL, NULL, NULL, NULL, '周赧王被迫迁居西周国王城，当时此处仍是西周国都；这是寄居避难，不表述为正式迁都。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('sui-moves-to-daxing', '隋文帝迁都大兴', 'politics', 'point', 'year', '开皇三年（583年）；新城营建与迁入按年精度记录。', 583, 12, 7007, NULL, NULL, NULL, NULL, NULL, NULL, '隋文帝迁入新建的大兴城，取代旧长安城成为隋朝都城。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('wu-zhou-moves-capital-to-luoyang', '武周迁都洛阳', 'politics', 'point', 'year', '天授元年（690年）；采用武周建立并以洛阳为都的年份。', 690, 12, 8291, NULL, NULL, NULL, NULL, NULL, NULL, '武则天称帝建立武周，以洛阳为都并称神都，政治中心由长安转至洛阳。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('tang-forced-move-to-luoyang', '昭宗东迁洛阳', 'politics', 'point', 'year', '天祐元年（904年）正月迁都；《旧唐书·昭宗本纪》记载此事。', 904, 12, 10859, NULL, NULL, NULL, NULL, NULL, NULL, '朱全忠迫使唐昭宗离开长安迁往洛阳，长安遭到毁坏，唐朝政治中心自此未能恢复。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('tang-restored-capital-to-changan', '唐中宗还都长安', 'politics', 'point', 'year', '神龙二年（706年）还都长安；武周复唐发生于705年。', 706, 12, 8483, NULL, NULL, NULL, NULL, NULL, NULL, '神龙政变后唐朝复辟，中宗次年还都长安，结束武周时期以洛阳为政治中心的阶段。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('song-moves-capital-to-linan', '南宋定都临安', 'politics', 'point', 'year', '绍兴八年（1138年）；此处取正式定临安为行在之年，不将此前数次临幸混作定都。', 1138, 12, 13667, NULL, NULL, NULL, NULL, NULL, NULL, '宋高宗正式以临安为行在，临安由此成为南宋长期的政治中心。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('ming-moves-capital-to-beijing', '永乐迁都北京', 'politics', 'point', 'year', '永乐十九年（1421年）正式迁都。', 1421, 12, 17063, NULL, NULL, NULL, NULL, NULL, NULL, '明成祖将都城由南京迁至北京，南京保留留都地位。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('roc-moves-wartime-government-to-chongqing', '国民政府迁都重庆', 'politics', 'point', 'month', '1937年11月国民政府决定迁渝；重庆市政协资料记载迁移过程。', 1937, 11, 23254, NULL, NULL, NULL, NULL, NULL, NULL, '抗日战争全面爆发后，国民政府迁往重庆，重庆成为战时陪都和全国抗战的重要政治中心。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('roc-returns-capital-to-nanjing', '国民政府还都南京', 'politics', 'point', 'month', '1946年5月还都南京。', 1946, 5, 23356, NULL, NULL, NULL, NULL, NULL, NULL, '抗战胜利后，国民政府由重庆还都南京。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('zhou-jingwang-moves-to-chengzhou', '周敬王迁都成周', 'politics', 'point', 'year', '前510年营建新城并迁居的通行系年；《左传》记王子朝之乱，迁居缘由见杜预注。', -510, 12, -6097, NULL, NULL, NULL, NULL, NULL, NULL, '王子朝之乱后，王城仍有其党羽活动。周敬王据杜预注的传统解释迁居王城以东的新成周，以避乱自安。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('later-jin-cedes-yanyun', '后晋割让燕云十六州', 'politics', 'point', 'year', '936年后晋建国及相关契丹册立、割地约定；具体交割过程跨越936年前后。', 936, 12, 11243, NULL, NULL, NULL, NULL, NULL, NULL, '石敬瑭借契丹援助赢得帝位，向辽割让燕云十六州，北方门户自此长期处于辽、金控制之下。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('later-zhou-recovers-ying-mo', '后周北伐收复瀛、莫二州', 'battle', 'point', 'year', '显德六年（959年）北伐；州县归属与进军阶段按年精度处理。', 959, 12, 11519, NULL, NULL, NULL, NULL, NULL, NULL, '后周世宗北伐，收复燕云南部的瀛州、莫州等地，但未能完成燕云十六州的整体收复。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('song-jin-maritime-alliance', '宋金海上之盟', 'politics', 'point', 'year', '宣和二年（1120年）订盟；条约内容与实际执行过程跨越1120—1123年。', 1120, 12, 13451, NULL, NULL, NULL, NULL, NULL, NULL, '宋与金约定夹攻辽，宋希望借此取得燕云；辽亡后宋金关系迅速破裂，最终引向靖康之变。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('song-recovers-yanyun-six-prefectures', '北宋短暂收复燕京及六州', 'politics', 'point', 'year', '宣和五年（1123年）；此处采用年精度，不把部分州县交割误写为十六州全部收复。', 1123, 12, 13487, NULL, NULL, NULL, NULL, NULL, NULL, '辽亡后金将燕京及附近六州交给北宋，宋短暂取得燕云南部，但实际控制很快因宋金冲突而动摇。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('jin-reclaims-yanyun', '金重新夺取燕云', 'battle', 'point', 'year', '1125—1126年金军重夺燕云并南下；以1125年为事件起点，靖康之变另有独立事件。', 1125, 12, 13511, NULL, NULL, NULL, NULL, NULL, NULL, '宋金矛盾激化后，金军重新控制燕云并南下攻宋，北宋北部防线崩溃，次年开封陷落。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('heirloom-seal-lost', '传国玉玺失踪', 'politics', 'circa', 'year', '传国玺失踪的具体时点与是否毁于火中存在记载差异，取后唐灭亡前后窗口。', 936, 12, 11243, 936, 1, 11232, 937, 12, 11255, '后唐末帝李从珂兵败自焚，传统记载称传国玉玺随之失去下落；此后宋太祖受禅时已不见传国玺。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('qin-unifies-china', '秦统一中国', 'politics', 'point', 'year', '秦王政二十六年，前221年；作为特别重大总纲事件保留，不等同于秦统一制度事件。', -221, 12, -2629, NULL, NULL, NULL, NULL, NULL, NULL, '秦灭齐完成六国统一，结束战国长期分裂，建立中国历史上第一个大一统帝国。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('western-han-protectorate-of-western-regions', '西域都护府建立', 'politics', 'point', 'year', '神爵二年，前60年；具体设置月份不详。', -60, 12, -697, NULL, NULL, NULL, NULL, NULL, NULL, '西汉在西域设置都护，标志中央政权对西域的经略由军事往来推进到持续行政管理。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('western-han-grace-order', '推恩令颁行', 'politics', 'point', 'year', '元朔二年（前127年）；《汉书·主父偃传》载偃建议推恩，武帝从其计。', -127, 12, -1501, NULL, NULL, NULL, NULL, NULL, NULL, '汉武帝采纳主父偃建议，允许诸侯王将封地分给子弟为列侯，由朝廷另立侯国。诸侯王国因此逐代析分，中央对地方的控制加强。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('western-han-salt-iron-monopoly', '盐铁官营', 'politics', 'point', 'year', '元狩四年（前119年）前后推行；盐铁专营的设置与各地落实并非单一日期。', -119, 12, -1405, NULL, NULL, NULL, NULL, NULL, NULL, '汉武帝将盐、铁经营纳入国家专营，由官府设官管理生产和销售，以增加财政收入、支持对匈奴战争。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('sui-establishes-jinshi-examination', '隋代设进士科', 'politics', 'point', 'year', '通行说法系于大业元年（605）；部分地方志记为大业二年（606），故按年精度记为制度开端的通行系年。', 605, 12, 7271, NULL, NULL, NULL, NULL, NULL, NULL, '隋炀帝设进士科，以考试选拔人才，成为科举制度形成的重要节点。此后考试取士逐步发展为历代官员选拔的重要途径。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('tang-two-tax-law', '两税法推行', 'politics', 'point', 'year', '建中元年（780年）颁行；《旧唐书·杨炎传》及《资治通鉴》记其制度与施行。', 780, 12, 9371, NULL, NULL, NULL, NULL, NULL, NULL, '唐德宗采纳杨炎建议，按居住地和资产等确定税额，分夏、秋两季征收，取代以丁身为主要依据的租庸调征收格局。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('tang-tubo-changqing-alliance', '唐蕃长庆会盟', 'politics', 'point', 'year', '长庆元年至二年（821—822年）分阶段立碑、会盟，采用821年作为事件锚点。', 821, 12, 9863, NULL, NULL, NULL, NULL, NULL, NULL, '唐与吐蕃订立长庆会盟，约定边界与和平关系，是唐蕃长期战争后重要的边疆秩序节点。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content) VALUES ('qing-establishes-ili-general', '清设伊犁将军', 'politics', 'point', 'year', '乾隆二十七年（1762年）；机构设置月份不详。', 1762, 12, 21155, NULL, NULL, NULL, NULL, NULL, NULL, '清廷在平定准噶尔后设置伊犁将军，建立对新疆军政事务的常设统辖机构。', NULL, NULL)
